                self.paged.control.scoped_stage(|control|{control.begin_stage(text.len())?;for byte in text.as_bytes(){self.inline.bytes[self.inline.length]=*byte;self.inline.length+=1;control.step()?;}Ok::<_,ValueError>(())})?;
