    fn projected(&mut self,source:&T,shape:Option<B>,path:&mut[usize;64],depth:usize,level:u16,output:&mut Output)->Result<(),PackRefusal>{
        level_limit(level,self.options.limits.max_depth.min(64))?;
        self.control.checkpoint()?;
