        }Ok(())
    }
    fn projected_fields<T:FieldProjectionSource>(&mut self,source:&T,spec:Option<&S>,ids:&[u16],path:&mut[usize;64],depth:usize,level:u16,maximum:u16,control:&mut NativeEncodeControl<'_>)->Result<(),PackRefusal>{
